+use crossterm::event::{Event, KeyCode, KeyEvent};
 use edtui::{EditorEventHandler, EditorMode, EditorState, Index2, Lines};

+/// Key codes edtui can convert; anything else makes it panic.
+fn edtui_handles(code: KeyCode) -> bool {
+    matches!(
+        code,
+        KeyCode::Char(_)
+            | KeyCode::Enter
+            | KeyCode::Esc
+            | KeyCode::Backspace
+            | KeyCode::Delete
+            | KeyCode::Tab
+            | KeyCode::Left
+            | KeyCode::Right
+            | KeyCode::Up
+            | KeyCode::Down
+            | KeyCode::Home
+            | KeyCode::End
+            | KeyCode::PageUp
+            | KeyCode::PageDown
+    )
+}
